# Phone (section 12.2): PhoneDial (dialler + call list), PhoneIncoming, PhoneInCall.
from gen import *
W, H = 320, 200
def phone(body):
    head = f'<div style="display: flex; align-items: center; gap: {s2}; font-size: {f12}; color: {t.mute}"><span>{tx("رقمي:")}</span><span style="font-family: {FF_MONO}">{ltr("UOS-XXXX-XXXX")}</span>{ibtn("نسخ رقم Ultar", "copy", "account.copy")}</div>'
    return appwindow('الهاتف', body, head)
def avatar():
    return f'<span style="width: {s7}; height: {s7}; flex: none; border-radius: {r_round}; background: {t.raised}; border: {HAIR} solid {t.ctl}; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center">{ic("user")}</span>'

begin('PhoneDial.dc.html')
def way(icon, label, text, on):
    return f'<button role="radio" aria-checked="{"true" if on else "false"}"{act("phone.way", label)}{"" if on else " tabindex=\"-1\""} style="flex: 1; min-height: {s7}; padding: {s1} {s3}; border-radius: {r_ctl}; background: {t.hover if on else "transparent"}; border: {RING if on else HAIR} solid {t.acctext if on else t.ctl}; box-sizing: border-box; display: flex; align-items: center; gap: {s2}">{ic("check", True) if on else ""}{ic(icon, True)}<span style="display: block"><span style="display: block; font-weight: {w6}">{tx(label)}</span><span style="display: block; font-size: {f12}; color: {t.mute}">{tx(text)}</span></span></button>'
ways = radiogroup('طريق الاتصال', way('cloud', 'رقم Ultar', 'مشفّرة', True) + way('cell', 'الشبكة الخلوية', 'SIM 1', False))
num = f'<div style="display: flex; align-items: center; gap: {s2}; height: {s7}; padding: 0 {s3}; border-radius: {r_ctl}; background: {t.raised}; border: {HAIR} solid {t.ctl}; box-sizing: border-box"><span style="font-family: {FF_MONO}; font-size: {f20}; color: {t.mute}">{ltr("UOS-")}</span><input type="tel" dir="ltr"{act("phone.number", "الرقم المطلوب")} aria-label="الرقم المطلوب" value="4821-77" style="flex: 1; height: 100%; font-family: {FF_MONO}; font-size: {f20}" />{ibtn("حذف آخر رقم", "backspace", "phone.backspace")}</div>'
sugg = f'<button{act("phone.suggest", "ليلى حداد")} aria-label="اقتراح: ليلى حداد" style="min-height: {s7}; padding: 0 {s2}; border-radius: {r_ctl}; display: flex; align-items: center; gap: {s3}">{ic("user", True)}<span style="flex: 1">ليلى حداد</span><span style="font-family: {FF_MONO}; font-size: {f12}; color: {t.mute}">{ltr("UOS-4821-7730")}</span></button>'
pad = f'<div role="group" aria-label="لوحة الأرقام" dir="ltr" style="display: grid; grid-template-columns: repeat(3, 1fr); gap: {s2}">' + ''.join(f'<button{act("phone.digit", d)} aria-label="{d}" style="height: {s7}; border-radius: {r_ctl}; background: {t.raised}; border: {HAIR} solid {t.ctl}; box-sizing: border-box; font-size: {f20}; font-weight: {w5}; text-align: center">{d}</button>' for d in '123456789*0#') + '</div>'
call = f'<div style="display: flex; gap: {s2}">{button("مكالمة فيديو", "phone.call.video", icon="video", grow=True)}{button("اتصال", "phone.call", "primary", icon="phone", grow=True)}</div>'
dial = f'<section aria-label="لوحة الاتصال" style="width: {g(100)}; flex: none; padding: {s5}; box-sizing: border-box; border-inline-end: {HAIR} solid {t.line}; display: flex; flex-direction: column; gap: {s3}">{h1("اتصال")}{ways}{num}{sugg}{pad}{call}</section>'
def entry(kind, name, way_, when):
    icon, word = {'in': ('call-in', 'واردة'), 'out': ('call-out', 'صادرة'), 'missed': ('call-missed', 'فائتة')}[kind]
    return f'<li style="min-height: {bar_h}; padding: {s2} {s4}; box-sizing: border-box; display: flex; align-items: center; gap: {s3}; border-bottom: {HAIR} solid {t.line}"><span style="display: inline-flex; color: {t.danger if kind == "missed" else t.mute}">{ic(icon)}</span><div style="flex: 1"><div style="font-weight: {w5}">{tx(name)}</div>{sub(f"{word} · {way_}", t.danger if kind == "missed" else None)}</div><span style="font-size: {f12}; color: {t.mute}">{tx(when)}</span>{ibtn("معاودة الاتصال: " + name, "phone", "phone.callback")}{ibtn("إجراءات أخرى: " + name, "more", "phone.entry.more")}</li>'
tabs = f'<div role="tablist" aria-label="تصفية السجلّ" style="display: flex; gap: {s1}">' + ''.join(f'<button role="tab" aria-selected="{"true" if on else "false"}"{act("phone.filter", n)} style="height: {tgt}; padding: 0 {s3}; border-radius: {r_ctl}; background: {t.hover if on else "transparent"}; font-weight: {w6 if on else w4}">{n}</button>' for n, on in (('الكل', True), ('الفائتة', False))) + '</div>'
log = f'<section aria-label="سجلّ المكالمات" style="flex: 1; min-width: 0; padding: {s5} {s6}; box-sizing: border-box; display: flex; flex-direction: column; gap: {s3}"><div style="display: flex; align-items: center; gap: {s4}">{h1("سجلّ المكالمات")}<span style="flex: 1"></span>{tabs}{ibtn("إعدادات الهاتف", "gear", "phone.settings")}</div>' + card(f'<ul role="list">{entry("missed", "ليلى حداد", "رقم Ultar", "اليوم 16:20")}{entry("out", "مكتب KM Code Craft", "SIM 1", "اليوم 11:05")}{entry("in", "UOS-2290-1184", "رقم Ultar", "أمس 19:42")}{entry("in", "+963 11 555 0142", "SIM 1", "20 تشرين الثاني")}{entry("out", "سامر", "رقم Ultar", "19 تشرين الثاني")}</ul>') + '</section>'
out('الهاتف – الاتصال', W, H, phone(dial + log), 'Telefon · Wählfeld und Anrufliste (§12.2)', 5)

begin('PhoneIncoming.dc.html')
inc = f'<main role="alertdialog" aria-label="مكالمة واردة من ليلى حداد" style="flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: {s5}">{avatar()}<div style="text-align: center"><div style="font-size: {f14}; color: {t.mute}">مكالمة صوتية واردة</div><div style="font-family: {FF_TITLE}; font-size: {f32}; font-weight: {w7}">ليلى حداد</div><div style="font-family: {FF_MONO}; font-size: {f16}">{ltr("UOS-4821-7730")}</div></div><div style="display: flex; gap: {s2}">{badge("عبر رقم Ultar", "info", "cloud")}{badge("مشفّرة من طرف إلى طرف", "ok", "secure")}</div><div style="display: flex; gap: {s4}">{button("رفض", "phone.decline", "danger", icon="hangup")}{button("رفض برسالة", "phone.decline.msg", icon="message")}{button("ردّ", "phone.accept", "primary", icon="phone")}</div>{sub("يظهر هذا أيضاً على شاشة القفل، وكشريط إذا كان تطبيق آخر في ملء الشاشة.")}</main>'
out('الهاتف – مكالمة واردة', W, H, phone(inc), 'Telefon · Eingehender Anruf (§12.2)', 5)

begin('PhoneInCall.dc.html')
def cbtn(icon, label, a, on=None, danger=False):
    st = '' if on is None else f' aria-pressed="{"true" if on else "false"}"'
    bd = t.danger if danger else (t.acctext if on else t.ctl)
    return f'<button{act(a, label)}{st} style="width: {g(26)}; padding: {s2} {s1}; box-sizing: border-box; border-radius: {r_ctl}; background: {t.hover if on else t.raised}; border: {RING if (on or danger) else HAIR} solid {bd}; color: {t.danger if danger else t.text}; display: flex; flex-direction: column; align-items: center; gap: {s1}; font-size: {f12}; text-align: center">{ic(icon)}<span>{tx(label)}</span></button>'
info = f'<div style="display: flex; align-items: center; gap: {s3}">{avatar()}<div style="flex: 1"><div style="font-family: {FF_TITLE}; font-size: {f20}; font-weight: {w7}">ليلى حداد</div><div style="display: flex; align-items: center; gap: {s2}; font-size: {f12}; color: {t.mute}"><span role="timer" aria-label="مدّة المكالمة">{ltr("02:14")}</span><span>·</span><span>{tx("عبر رقم Ultar")}</span></div></div>{badge("مشفّرة من طرف إلى طرف", "ok", "secure")}{badge("الاتصال جيّد", "ok", "cell")}</div>'
video = f'<div style="flex: 1; min-height: 0; position: relative; border-radius: {r_card}; background: {t.surface}; border: {HAIR} solid {t.line}; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: {s2}; color: {t.mute}">{ic("user")}<span>صورة ليلى حداد (عنصر نائب للفيديو)</span><div style="position: absolute; bottom: {s4}; inset-inline-end: {s4}; width: {g(48)}; height: {g(32)}; border-radius: {r_ctl}; background: {t.raised}; border: {HAIR} solid {t.ctl}; box-sizing: border-box; display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: {f12}">{ic("video", True)}<span>صورتك</span></div></div>'
bar = f'<div role="toolbar" aria-label="التحكّم بالمكالمة" style="display: flex; justify-content: center; gap: {s2}">{cbtn("mic", "كتم الميكروفون", "phone.mute", False)}{cbtn("speaker", "مخرج الصوت", "phone.output")}{cbtn("keypad", "لوحة الأرقام", "phone.keypad")}{cbtn("pause", "تعليق", "phone.hold", False)}{cbtn("video", "الفيديو", "phone.video", True)}{cbtn("camera-switch", "تبديل الكاميرا", "phone.camera")}{cbtn("screen-share", "مشاركة الشاشة", "phone.share", False)}{cbtn("hangup", "إنهاء المكالمة", "phone.hangup", danger=True)}</div>'
out('الهاتف – أثناء المكالمة', W, H, phone(f'<main aria-label="مكالمة فيديو مع ليلى حداد" style="flex: 1; min-width: 0; padding: {s5} {s6}; box-sizing: border-box; display: flex; flex-direction: column; gap: {s4}">{info}{video}{bar}</main>'), 'Telefon · Gespräch mit Video-Steuerung (§12.2)', 5)
